function A({registerIndicator:b,sourceValues:y,nulls:v}){b({id:"oa-gdema",name:"Generalized Double Exponential Moving Average (GDEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"vfactor",type:"number",label:"Volume Factor (v)",default:1,min:0,max:3,step:.1,tooltip:"0=EMA, 1=standard DEMA, >1=more aggressive lag removal"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"gdema",type:"line",title:"GDEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,a){const M=Math.max(1,Math.floor(Number(a.period)||10)),i=Number(a.vfactor),u=a.vfactor==null||a.vfactor===""||!Number.isFinite(i)?1:Math.min(3,Math.max(0,i)),h=y(c,a.source??"close"),l=2/(M+1),g=1-l;let d=!0,n=1,t=0,e=0,o=0,m=0;const s=new Array(c.length).fill(NaN);for(let r=0;r<c.length;r++){const f=h[r];if(Number.isFinite(f)){if(t=l*(f-t)+t,d){n*=g;const p=1/(1-n);o=p*t,e=l*(o-e)+e,m=p*e,d=n>1e-10}else o=t,e=l*(o-e)+e,m=e;s[r]=(1+u)*o-u*m}}return{gdema:v(s)}}})}export{A as default};
